// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max);
        address owner = c.owner();
        uint256 balBefore = address(c).balance;
        uint256 ownerBefore = owner.balance;
        bool ok;
        vm.prank(owner);
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        uint256 balAfter = address(c).balance;
        uint256 ownerAfter = owner.balance;
        bool correct = !ok || (balBefore - balAfter == amount && ownerAfter - ownerBefore == amount);
        assertTrue(correct);
    }
}
